Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <iomanip>
using namespace std;

using ll = long long;
using ld = long double;
using ull = unsigned long long;

const int dirX[4] = {1, -1, 0, 0};
const int dirY[4] = {0, 0, 1, -1};

int gridSize, timeLimit, startX, startY;
string labGrid[20], sciGrid[20];
int memoTable[12][12][12][12][62];
int edgeCap[250][250], parentArr[250];
int shortestDist[20][20], visitedArr[20][20];

bool inBounds(int x, int y) {
    return x >= 0 && x < gridSize && y >= 0 && y < gridSize && labGrid[x][y] != 'Y' && labGrid[x][y] != 'Z';
}

void computeDistances() {
    memset(shortestDist, 0x3f, sizeof(shortestDist));
    memset(visitedArr, 0, sizeof(visitedArr));
    shortestDist[startX][startY] = 0;
    visitedArr[startX][startY] = 1;
    queue<int> qx, qy;
    qx.push(startX);
    qy.push(startY);
    while (!qx.empty()) {
        int x = qx.front(); qx.pop();
        int y = qy.front(); qy.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dirX[k];
            int ny = y + dirY[k];
            if (inBounds(nx, ny) && !visitedArr[nx][ny]) {
                shortestDist[nx][ny] = shortestDist[x][y] + 1;
                visitedArr[nx][ny] = 1;
                qx.push(nx);
                qy.push(ny);
            }
        }
    }
}

bool canReach(int x0, int y0, int x1, int y1, int steps) {
    if (steps > timeLimit) return false;
    int& res = memoTable[x0][y0][x1][y1][steps];
    if (res != -1) return res;
    if (x0 == x1 && y0 == y1) return res = (shortestDist[x0][y0] >= steps);
    if (shortestDist[x0][y0] <= steps) return res = false;
    for (int k = 0; k < 4; ++k) {
        int nx = x0 + dirX[k];
        int ny = y0 + dirY[k];
        if (inBounds(nx, ny) && canReach(nx, ny, x1, y1, steps + 1)) {
            return res = true;
        }
    }
    return res = false;
}

bool bfsFlow(int source, int sink) {
    memset(parentArr, -1, sizeof(parentArr));
    parentArr[source] = -2;
    queue<int> q;
    q.push(source);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int i = source; i <= sink; ++i) {
            if (parentArr[i] == -1 && edgeCap[v][i] > 0) {
                parentArr[i] = v;
                q.push(i);
            }
        }
    }
    return parentArr[sink] != -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(32);

    cin >> gridSize >> timeLimit;
    for (int i = 0; i < gridSize; ++i) cin >> sciGrid[i];
    for (int i = 0; i < gridSize; ++i) cin >> labGrid[i];

    vector<pair<int, int>> points;
    vector<int> labCaps, sciCaps;
    for (int i = 0; i < gridSize; ++i) {
        for (int j = 0; j < gridSize; ++j) {
            if (sciGrid[i][j] == 'Z') {
                startX = i;
                startY = j;
            } else if (isdigit(sciGrid[i][j])) {
                points.emplace_back(i, j);
                labCaps.push_back(labGrid[i][j] - '0');
                sciCaps.push_back(sciGrid[i][j] - '0');
            }
        }
    }

    int numPoints = points.size();
    memset(edgeCap, 0, sizeof(edgeCap));
    for (int i = 0; i < numPoints; ++i) {
        edgeCap[0][i + 1] = sciCaps[i];
        edgeCap[numPoints + 1 + i][2 * numPoints + 1] = labCaps[i];
    }

    computeDistances();
    memset(memoTable, -1, sizeof(memoTable));
    for (int i = 0; i < numPoints; ++i) {
        for (int j = 0; j < numPoints; ++j) {
            if (canReach(points[i].first, points[i].second, points[j].first, points[j].second, 0)) {
                edgeCap[i + 1][numPoints + 1 + j] = 1000;
            }
        }
    }

    int totalFlow = 0;
    while (bfsFlow(0, 2 * numPoints + 1)) {
        int sinkNode = 2 * numPoints + 1;
        int flowAmount = 1000000;
        while (parentArr[sinkNode] >= 0) {
            flowAmount = min(flowAmount, edgeCap[parentArr[sinkNode]][sinkNode]);
            sinkNode = parentArr[sinkNode];
        }
        sinkNode = 2 * numPoints + 1;
        while (parentArr[sinkNode] >= 0) {
            edgeCap[parentArr[sinkNode]][sinkNode] -= flowAmount;
            edgeCap[sinkNode][parentArr[sinkNode]] += flowAmount;
            sinkNode = parentArr[sinkNode];
        }
        totalFlow += flowAmount;
    }

    cout << totalFlow;
    return 0;
}
